'use strict';

const { writeFileSync } = require('node:fs');
const { resolve } = require('node:path');
const { renderOtpEmail } = require('../server/domain/notification-templates.cjs');

const sampleCode = '170483';
const template = renderOtpEmail(sampleCode);
const source = [
  '// Generated by scripts/sync-apps-script-otp.cjs from the shared email layout.',
  'function buildOtpMail_(code) {',
  "  if (typeof code !== 'string' || !/^\\d{6}$/.test(code)) throw new TypeError('Invalid verification code');",
  '  const html = [',
  ...template.htmlBody.split('\n').map(line => '    ' + JSON.stringify(line) + ','),
  "  ].join('\\n');",
  '  return {',
  `    subject: ${JSON.stringify(template.subject)},`,
  `    body: ${JSON.stringify(template.body)}.split('${sampleCode}').join(code),`,
  `    htmlBody: html.split('${sampleCode}').join(code)`,
  '  };',
  '}',
  ''
].join('\n');

writeFileSync(resolve(__dirname, '../integrations/apps-script-otp/OtpTemplate.gs'), source);
